<!-- wp:wdl/lw-pr-custom-title-11 {"mainTitle":"3つの節目","subTitle":"OUR HISTORY","headingLevel":2,"colorMain":"#8c2f39","colorMainText":"#ffffff","colorSubText":"#f0d6d9","borderRadius":4} -->
<div class="wp-block-wdl-lw-pr-custom-title-11 lw-pr-custom-title-11" style="--color-main:#8c2f39;--color-main-text:#ffffff;--color-sub-text:#f0d6d9;width:100%;margin:1em auto" id="history"><h2 class="ttl" style="border-radius:4px"><span class="sub">OUR HISTORY</span><span class="main">3つの節目</span></h2></div>
<!-- /wp:wdl/lw-pr-custom-title-11 -->
<!-- wp:wdl/lw-space-1 {"pcHeight":16,"tbHeight":16,"spHeight":12} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:16px"></div><div class="tb" style="height:16px"></div><div class="sp" style="height:12px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:paragraph {"align":"center","style":{"color":{"text":"#3d3436"},"typography":{"fontSize":"16px","lineHeight":"2"},"spacing":{"margin":{"top":"28px","bottom":"24px"}}}} -->
<p class="has-text-align-center has-text-color" style="color:#3d3436;font-size:16px;line-height:2;margin-top:28px;margin-bottom:24px">55年のあいだに、大きく変わったことが3回ありました。<span class="lw-br on_500px"></span>年表よりも、そのときに何を決めたかを書いておきます。</p>
<!-- /wp:paragraph -->
<!-- wp:wdl/lw-space-1 {"pcHeight":24,"tbHeight":20,"spHeight":16} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:24px"></div><div class="tb" style="height:20px"></div><div class="sp" style="height:16px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:wdl/lw-pr-content-8 {"imageUrl":"https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/atelier_02.webp","imageAlt":"創業当時の工房","maxWidth":1040,"bgColor":"#ffffff","borderWidth":2,"borderColor":"#e7d6d8","bdrPc":10,"bdrSp":10,"minHeight":340} -->
<div class="wp-block-wdl-lw-pr-content-8 lw-pr-content-8" style="--content-8-max-w:1040px;--content-8-bdr-pc:10px;--content-8-bdr-sp:10px;--content-8-min-h:340px;background:#ffffff;border:2px solid #e7d6d8"><div class="image"><img loading="lazy" src="https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/atelier_02.webp" alt="創業当時の工房"/></div><div class="content_in"><!-- wp:paragraph {"style":{"typography":{"fontSize":"15px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"6px"}}}} -->
<p style="font-size:15px;line-height:1.6;margin-top:0px;margin-bottom:6px"><strong style="color:#8c2f39;font-size:15px;letter-spacing:.08em">1971年</strong></p>
<!-- /wp:paragraph -->
<!-- wp:heading {"level":3,"style":{"color":{"text":"#3a1c20"},"typography":{"fontSize":"22px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"16px"}}},"textAlign":"left"} -->
<h3 class="has-text-align-left has-text-color" style="color:#3a1c20;font-size:22px;line-height:1.6;margin-top:0px;margin-bottom:16px">旋盤2台から始めました</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"color":{"text":"#3d3436"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#3d3436;font-size:16px;line-height:1.9">町工場の一角を借りて、創業者ひとりで始めました。「断らない」を通した人で、採算の合わない仕事も引き受けては、夜中まで削っていたそうです。そのときの取引先が、いまも3社残っています。</p>
<!-- /wp:paragraph --></div></div>
<!-- /wp:wdl/lw-pr-content-8 -->
<!-- wp:wdl/lw-pr-content-8 {"imageUrl":"https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/atelier_03.webp","imageAlt":"工場の中","maxWidth":1040,"bgColor":"#ffffff","borderWidth":2,"borderColor":"#e7d6d8","bdrPc":10,"bdrSp":10,"minHeight":340} -->
<div class="wp-block-wdl-lw-pr-content-8 lw-pr-content-8" style="--content-8-max-w:1040px;--content-8-bdr-pc:10px;--content-8-bdr-sp:10px;--content-8-min-h:340px;background:#ffffff;border:2px solid #e7d6d8"><div class="image"><img loading="lazy" src="https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/atelier_03.webp" alt="工場の中"/></div><div class="content_in"><!-- wp:paragraph {"style":{"typography":{"fontSize":"15px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"6px"}}}} -->
<p style="font-size:15px;line-height:1.6;margin-top:0px;margin-bottom:6px"><strong style="color:#8c2f39;font-size:15px;letter-spacing:.08em">1998年</strong></p>
<!-- /wp:paragraph -->
<!-- wp:heading {"level":3,"style":{"color":{"text":"#3a1c20"},"typography":{"fontSize":"22px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"16px"}}},"textAlign":"left"} -->
<h3 class="has-text-align-left has-text-color" style="color:#3a1c20;font-size:22px;line-height:1.6;margin-top:0px;margin-bottom:16px">いちばん苦しかった年</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"color":{"text":"#3d3436"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#3d3436;font-size:16px;line-height:1.9">売上の6割を占めていた1社との取引が終わりました。人を減らさずに済ませるため、それまで受けていなかった「1個ずつの試作」を引き受けることにしました。手間はかかりますが、いまの柱はこのときに生まれたものです。</p>
<!-- /wp:paragraph --></div></div>
<!-- /wp:wdl/lw-pr-content-8 -->
<!-- wp:wdl/lw-pr-content-8 {"imageUrl":"https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/concept_01.webp","imageAlt":"若い職人が働く工場","maxWidth":1040,"bgColor":"#ffffff","borderWidth":2,"borderColor":"#e7d6d8","bdrPc":10,"bdrSp":10,"minHeight":340} -->
<div class="wp-block-wdl-lw-pr-content-8 lw-pr-content-8" style="--content-8-max-w:1040px;--content-8-bdr-pc:10px;--content-8-bdr-sp:10px;--content-8-min-h:340px;background:#ffffff;border:2px solid #e7d6d8"><div class="image"><img loading="lazy" src="https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/concept_01.webp" alt="若い職人が働く工場"/></div><div class="content_in"><!-- wp:paragraph {"style":{"typography":{"fontSize":"15px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"6px"}}}} -->
<p style="font-size:15px;line-height:1.6;margin-top:0px;margin-bottom:6px"><strong style="color:#8c2f39;font-size:15px;letter-spacing:.08em">2019年</strong></p>
<!-- /wp:paragraph -->
<!-- wp:heading {"level":3,"style":{"color":{"text":"#3a1c20"},"typography":{"fontSize":"22px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"16px"}}},"textAlign":"left"} -->
<h3 class="has-text-align-left has-text-color" style="color:#3a1c20;font-size:22px;line-height:1.6;margin-top:0px;margin-bottom:16px">若い人が入るようになった</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"color":{"text":"#3d3436"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#3d3436;font-size:16px;line-height:1.9">図面のやり取りをすべてデータに変え、土曜を休みにしました。以来7年で6人が入り、辞めた人はいません。設備よりも先に、ここを直すべきだったと思っています。</p>
<!-- /wp:paragraph --></div></div>
<!-- /wp:wdl/lw-pr-content-8 -->
<!-- wp:wdl/lw-space-1 {"pcHeight":80,"tbHeight":64,"spHeight":40} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:80px"></div><div class="tb" style="height:64px"></div><div class="sp" style="height:40px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
